$r=supabaseRequest('GET','/rest/v1/guests?select=*&user_id=eq.'.rawurlencode($_SESSION['user_id']).'&order=created_at.desc',null,authToken());$guests=(!$r['error']&&is_array($r['data']))?$r['data']:[];
