?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KaMi Wedding Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>:root{--k:#514332;--bg:#f5f2ec}body{background:var(--bg);color:#29251f}.sidebar{width:250px;background:#2f2923;min-height:100vh}.sidebar .nav-link{color:#d8d0c7;border-radius:12px;margin:3px 0}.sidebar .nav-link.active,.sidebar .nav-link:hover{background:#51473b;color:#fff}.brand{color:#fff;font-weight:800;font-size:21px}.card{border:1px solid #e5ddd2;border-radius:18px}.btn-kami{background:var(--k);color:#fff}.btn-kami:hover{background:#403428;color:#fff}.icon-btn{width:42px;height:42px;padding:0;display:inline-flex;align-items:center;justify-content:center;font-size:18px}.badge-soft{background:#e2f2e7;color:#247042}.badge-pending{background:#eee9e1;color:#766b60}@media(max-width:768px){.sidebar{width:72px}.brand-text,.nav-text,.logout-text{display:none}.sidebar .nav-link{justify-content:center}.content{width:calc(100% - 72px)}} </style></head><body><div class="d-flex"><aside class="sidebar p-3 d-flex flex-column flex-shrink-0"><div class="brand px-2 py-2 mb-4"><i class="bi bi-heart-fill me-2"></i><span class="brand-text">KaMi Wedding</span></div><nav class="nav nav-pills flex-column"><a class="nav-link <?=active('dashboard',$page)?>" href="dashboard.php?page=dashboard"><i class="bi bi-grid me-md-2"></i><span class="nav-text">Dashboard</span></a><a class="nav-link <?=active('guests',$page)?>" href="dashboard.php?page=guests"><i class="bi bi-people me-md-2"></i><span class="nav-text">Data Tamu</span></a><?php if(isKhaikal()):?><a class="nav-link <?=active('config',$page)?>" href="dashboard.php?page=config"><i class="bi bi-gear me-md-2"></i><span class="nav-text">Config</span></a><?php endif;?></nav><a class="nav-link text-danger-emphasis bg-light mt-auto" href="logout.php"><i class="bi bi-box-arrow-right me-md-2"></i><span class="logout-text">Logout</span></a></aside><main class="content flex-grow-1"><div class="container-fluid p-3 p-md-4 p-lg-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1"><?=e($page==='guests'?'Data Tamu':($page==='config'?'Config':'Dashboard'))?></h1><div class="text-secondary">KaMi Wedding Invitation</div></div><div class="badge text-bg-light border p-2"><i class="bi bi-person-fill me-1"></i><?=e(USERS[currentUser()]['label'])?></div></div><?php if($flash):?><div class="alert alert-<?=$flash[0]?>"><?=e($flash[1])?></div><?php endif;?><?php if($page==='dashboard'):?><div class="row g-3"><div class="col-md-4"><div class="card p-4"><div class="text-secondary">Total Tamu</div><div class="display-6 fw-bold"><?=$total?></div></div></div><div class="col-md-4"><div class="card p-4"><div class="text-secondary">Terkirim</div><div class="display-6 fw-bold"><?=$sent?></div></div></div><div class="col-md-4"><div class="card p-4"><div class="text-secondary">Belum Terkirim</div><div class="display-6 fw-bold"><?=$total-$sent?></div></div></div></div><div class="card p-4 mt-3"><h5>Selamat datang, <?=e(USERS[currentUser()]['label'])?> 👋</h5><p class="text-secondary mb-0">Kelola daftar tamu dan kirim undangan WhatsApp.</p></div><?php elseif($page==='guests'):?><div class="d-flex flex-column flex-md-row justify-content-between gap-2 mb-3"><input id="search" class="form-control" placeholder="Cari nama / phone..." style="max-width:450px"><a class="btn btn-kami" href="dashboard.php?page=guests&edit=new"><i class="bi bi-plus-lg me-1"></i>Tambah Data</a></div><div class="card overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0" id="guestTable"><thead><tr><th>Nama</th><th>Phone</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($guests as $g):$copyMsg=str_replace(['{{nama}}','{{link}}'],[$g['name'],inviteLink($g['name'],$cfg['invite_link']??BASE_INVITE)],$cfg['whatsapp_template']??DEFAULT_TEMPLATE);?><tr><td class="fw-semibold"><?=e($g['name'])?></td><td><?=e($g['phone'])?></td><td><span class="badge rounded-pill <?=($g['status']??'')==='Terkirim'?'badge-soft':'badge-pending'?>"><?=e($g['status']??'Belum')?></span></td><td><div class="d-flex justify-content-end gap-1"><a class="btn btn-light border icon-btn" title="Edit" href="dashboard.php?page=guests&edit=<?=e($g['id'])?>"><i class="bi bi-pencil"></i></a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="send_wa"><input type="hidden" name="id" value="<?=e($g['id'])?>"><button class="btn btn-kami icon-btn" type="submit" title="Kirim WhatsApp"><i class="bi bi-whatsapp"></i></button></form><button class="btn btn-light border icon-btn copy-message-btn" type="button" title="Salin Pesan" data-message="<?=e($copyMsg)?>"><i class="bi bi-copy"></i></button><form method="post" onsubmit="return confirm('Hapus data tamu ini?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_guest"><input type="hidden" name="id" value="<?=e($g['id'])?>"><button class="btn btn-outline-danger icon-btn" type="submit" title="Delete"><i class="bi bi-trash3"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$guests):?><tr><td colspan="4" class="text-center text-secondary py-5">Belum ada data tamu.</td></tr><?php endif;?></tbody></table></div></div><?php elseif($page==='config'):?><div class="card p-4"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_config"><div class="mb-3"><label class="form-label fw-semibold">Link Undangan</label><input class="form-control" name="invite_link" value="<?=e($cfg['invite_link'])?>"></div><div class="mb-3"><label class="form-label fw-semibold">Template WhatsApp</label><textarea class="form-control" name="whatsapp_template" rows="18"><?=e($cfg['whatsapp_template'])?></textarea></div><button class="btn btn-kami">Simpan Config</button></form></div><?php endif;?><?php if($page==='guests'&&isset($_GET['edit'])):$new=$edit==='new';?><div class="modal fade show d-block" style="background:#0006"><div class="modal-dialog modal-dialog-centered"><div class="modal-content rounded-4"><form method="post"><div class="modal-header"><h5 class="modal-title"><?=$new?'Tambah Data':'Edit Data'?></h5><a href="dashboard.php?page=guests" class="btn-close"></a></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_guest"><input type="hidden" name="id" value="<?=$new?'':e($eg['id']??'')?>"><div class="mb-3"><label class="form-label">Nama</label><input class="form-control" name="name" value="<?=e($new?'':($eg['name']??''))?>" required autofocus></div><div><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e($new?'':($eg['phone']??''))?>" placeholder="08123456789" required></div></div><div class="modal-footer"><a class="btn btn-light" href="dashboard.php?page=guests">Batal</a><button class="btn btn-kami">Simpan</button></div></form></div></div></div><?php endif;?></div></main></div><div class="modal fade" id="copyModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content rounded-4"><div class="modal-header"><h5 class="modal-title">Pesan Undangan</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><textarea id="copyText" class="form-control" rows="14" readonly></textarea></div><div class="modal-footer"><button type="button" class="btn btn-kami" id="copyNow"><i class="bi bi-copy me-1"></i> Salin Pesan</button></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>const s=document.getElementById('search');if(s)s.oninput=()=>{let q=s.value.toLowerCase();document.querySelectorAll('#guestTable tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')};let selectedMessage='';const copyModalEl=document.getElementById('copyModal');const copyModal=copyModalEl?new bootstrap.Modal(copyModalEl):null;document.querySelectorAll('.copy-message-btn').forEach(btn=>btn.addEventListener('click',()=>{selectedMessage=btn.dataset.message||'';document.getElementById('copyText').value=selectedMessage;if(copyModal)copyModal.show()}));document.getElementById('copyNow')?.addEventListener('click',async()=>{const ta=document.getElementById('copyText');ta.focus();ta.select();try{await navigator.clipboard.writeText(selectedMessage);alert('Pesan berhasil disalin.')}catch(e){try{document.execCommand('copy');alert('Pesan berhasil disalin.')}catch(e2){alert('Silakan tekan Ctrl+C untuk menyalin pesan.')}}});</script></body></html>